import logging
import re

from mcp.server.fastmcp import FastMCP

from netops.devices import run_on_device   # uses a read-only TACACS+ role

log = logging.getLogger("netops-mcp")
mcp = FastMCP("netops-readonly")

INVENTORY = {"sw1.example.com", "sw2.example.com", "r1.example.com"}
ALLOWED_SHOW = [
    re.compile(r"show (ip )?interfaces?( brief| status)?( [A-Za-z]+[0-9/.]+)?"),
    re.compile(r"show (ip route|ip ospf neighbor|cdp neighbors|logging last [0-9]{1,3})"),
]
SECRETS = re.compile(r"\b(secret|password|community|key-string)(\s+[0-9])?\s+\S+", re.IGNORECASE)


def check_command(cmd: str) -> str:
    if any(ch in cmd for ch in "|;\n\r"):            # no pipes, chaining or line breaks
        raise PermissionError("command rejected: forbidden characters")
    cmd = " ".join(cmd.split())
    if not any(p.fullmatch(cmd) for p in ALLOWED_SHOW):
        raise PermissionError("command rejected: not on the read-only allowlist")
    return cmd


def redact(text: str) -> str:
    return SECRETS.sub(lambda m: f"{m.group(1)} <redacted>", text)


@mcp.tool()
def run_show(device: str, command: str) -> dict:
    """Run an allowlisted, read-only show command on an inventory device."""
    if device not in INVENTORY:
        raise ValueError("unknown device")
    safe = check_command(command)                    # enforced in code, not in the prompt
    output = run_on_device(device, safe)
    log.info("tool=run_show device=%s command=%r", device, safe)
    # Label device text as data so the agent and the reviewer treat it as untrusted
    return {"device": device, "command": safe, "untrusted_device_output": redact(output)}

